        return None

    def clamp_step(n):
        if n < -1:
            return -1
        if n > 1:
            return 1
        return n

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def add(a, b):
        return (a[0] + b[0], a[1] + b[1])

    def get_pos():
        for k in ("self_pos", "position", "pos", "agent_pos", "agent_position", "location"):
            p = to_xy(observation.get(k))
