        if value is None:
            return pts
        if isinstance(value, dict):
            for v in value.values():
                pts.extend(extract_points(v))
            return pts
        if isinstance(value, (list, tuple)):
            if len(value) >= 2 and all(isinstance(x, (int, float)) for x in value[:2]):
                pts.append((value[0], value[1]))
            else:
                for v in value:
                    pts.extend(extract_points(v))
        return pts

    def get_points(keys):
        pts = []
        for k in keys:
            pts.extend(extract_points(observation.get(k)))
        seen = set()
        out = []
        for p in pts:
