                p = None
                for k in ("pos", "position", "location"):
                    p = to_xy(a.get(k))
                    if p is not None:
                        break
                if p is not None:
                    kind = str(a.get("team", a.get("side", a.get("type", ""))))
                    if kind and ("enemy" in kind or "oppo" in kind or "pred" in kind):
                        threats.append(p)
