                threats.append(p)

    # Walls / obstacles / blocked cells
    blocked = set()
    for k in ("walls", "obstacles", "blocked", "occupied", "hazards", "traps"):
        for p in extract_points(observation.get(k)):
            blocked.add(p)

    # Bounds if available
    width = observation.get("width")
    height = observation.get("height")
    grid = observation.get("grid")
    if isinstance(grid, (list, tuple)) and grid:
        if height is None:
