        if width is not None and (p[0] < 0 or p[0] >= width):
            return False
        if height is not None and (p[1] < 0 or p[1] >= height):
            return False
        return True

    def danger_at(p):
        d = 0
        for t in threats:
            dist = manhattan(p, t)
            if dist == 0:
                d += 50
            else:
                d += max(0, 8 - dist) * 2
        return d

    def target_attraction(p):
        if not targets:
            return 0
        best = None
        for t in targets:
            dist = manhattan(p, t)
            if best is None or dist < best:
                best = dist
        return -best if best is not None else 0

    # If pursuing/evading, threats matter more; if collection/territory, targets matter more.
    if "evad" in role or "flee" in role:
        threat_w = 5
        target_w = 1
    elif "purs" in role or "hunt" in role or "chase" in role:
        threat_w = 2
        target_w = 4
    elif "territ" in role or "control" in role:
        threat_w = 2
        target_w = 4
    else:
