            continue
        score = 0
        score += target_w * target_attraction(nxt)
        score -= threat_w * danger_at(nxt)

        # Prefer staying put only if already in danger or on target
        if mv == (0, 0):
            score -= 1

        # Small bias toward center if no info
        if width is not None and height is not None:
            cx = (width - 1) / 2.0
            cy = (height - 1) / 2.0
            score -= 0.01 * (abs(nxt[0] - cx) + abs(nxt[1] - cy))

        # Avoid hugging allies if we have many and no targets
        if allies and not targets:
            for a in allies:
                if a != me and manhattan(nxt, a) == 0:
                    score -= 5

        if best_score is None or score > best_score:
            best_score = score
            best_move = mv

    dx = clamp_step(best_move[0])
    dy = clamp_step(best_move[1])
    return [dx, dy]

